#!/usr/bin/env python3\n\nimport subprocess\nimport sys\nimport os\n\nos.chdir('/Users/ajaydwivedi/Documents/Github/Personal/PostgreSQL-Learning/Debezium-CDC-Kafka')\n\nprint(\"=\"*80)\nprint(\"RUNNING DEPLOYMENT PLAYBOOK\")\nprint(\"=\"*80)\nprint()\n\n# Run the playbook\ncmd = [\n    'ansible-playbook',\n    '-i', 'hosts.yml',\n    'playbook-deploy-all.yml',\n    '--vault-password-file=vault-pass',\n    '-v'\n]\n\nprint(f\"Command: {' '.join(cmd)}\")\nprint()\n\ntry:\n    proc = subprocess.Popen(\n        cmd,\n        stdout=subprocess.PIPE,\n        stderr=subprocess.STDOUT,\n        text=True,\n        bufsize=1\n    )\n    \n    # Write output to file in real-time\n    with open('ansible_output.log', 'w') as log_file:\n        for line in proc.stdout:\n            log_file.write(line)\n            log_file.flush()\n            print(line, end='')\n    \n    returncode = proc.wait()\n    print()\n    print(\"=\"*80)\n    print(f\"DEPLOYMENT COMPLETED WITH EXIT CODE: {returncode}\")\n    print(\"=\"*80)\n    \n    if returncode == 0:\n        print(\"✅ DEPLOYMENT SUCCESSFUL\")\n    else:\n        print(\"❌ DEPLOYMENT FAILED\")\n    \n    sys.exit(returncode)\n    \nexcept Exception as e:\n    print(f\"ERROR: {e}\")\n    sys.exit(1)\n"
